//! Interop with the license server: `tests/vectors.json` is generated by the server repo (`scripts/make_vectors.py`)
//! with a test-only key. This Rust verifier must give the same answer for every case.

use license::{device, token};
use serde_json::Value;

fn hex(s: &str) -> Vec<u8> {
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap()).collect()
}

fn vectors() -> Value {
    serde_json::from_str(include_str!("vectors.json")).unwrap()
}

#[test]
fn every_shared_case_gets_the_expected_answer() {
    let v = vectors();
    let pk: [u8; 32] = hex(v["public_key_hex"].as_str().unwrap()).try_into().unwrap();
    let cases = v["cases"].as_array().unwrap();
    assert!(cases.len() >= 10);
    for c in cases {
        let current: Vec<String> = c["current"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
        let got = token::verify(c["token"].as_str().unwrap(), &pk, &current, c["now"].as_u64().unwrap());
        let expect = c["expect"].as_str().unwrap();
        match (expect, &got) {
            ("ok", Ok(_)) => {}
            (e, Err(err)) if err.code() == e => {}
            _ => panic!("case {:?}: expected {expect}, got {got:?}", c["name"]),
        }
    }
}

#[test]
fn device_codes_made_here_equal_the_ones_the_server_made() {
    let v = vectors();
    for pc in ["pc_a", "pc_b", "junk"] {
        let c = &v["components"][pc];
        let get = |k: &str| c[k].as_str().map(String::from);
        let comps = device::Components { guid: get("guid"), bios: get("bios"), cpu: get("cpu"), disk: get("disk") };
        assert_eq!(device::device_code(&comps), v["device_codes"][pc].as_str().unwrap(), "{pc}");
    }
}
